#!/usr/bin/env python3
import sys
import json
import re
import argparse
from datetime import datetime, timedelta, timezone

def parse_date(date_str):
    for fmt in ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S %Z", "%Y-%m-%dT%H:%M:%S.%fZ"):
        try:
            return datetime.strptime(date_str, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    try:
        # Try fromisoformat as a fallback
        return datetime.fromisoformat(date_str.replace('Z', '+00:00'))
    except ValueError:
        return None

class Expression:
    def eval(self, record):
        raise NotImplementedError()

class Literal(Expression):
    def __init__(self, value):
        self.value = value
    def eval(self, record):
        return self.value

class Field(Expression):
    def __init__(self, name):
        self.name = name
    def eval(self, record):
        # Handle nested fields
        parts = self.name.split('.')
        val = record
        for part in parts:
            if isinstance(val, dict) and part in val:
                val = val[part]
            else:
                return None
        return val

class BinOp(Expression):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right
    def eval(self, record):
        l = self.left.eval(record)
        r = self.right.eval(record)
        if l is None or r is None: return None
        try:
            if self.op == '+': return l + r
            if self.op == '-': return l - r
            if self.op == '*': return l * r
            if self.op == '/': return l / r
            if self.op == '==': return l == r
            if self.op == '!=': return l != r
            if self.op == '>': return l > r
            if self.op == '<': return l < r
            if self.op == '>=': return l >= r
            if self.op == '<=': return l <= r
        except:
            return None
        return None

class FuncCall(Expression):
    def __init__(self, name, args):
        self.name = name
        self.args = args
    def eval(self, record):
        args = [arg.eval(record) for arg in self.args]
        if self.name == 'length':
            return len(str(args[0])) if args[0] is not None else 0
        if self.name == 'parseDate':
            return parse_date(args[0]) if args[0] is not None else None
        return None

def parse_expression(s):
    # Very simple expression parser for now
    s = s.strip()
    # Check for binops (simplified)
    for op in ['==', '!=', '>=', '<=', '>', '<', '+', '-', '*', '/']:
        if op in s:
            # Avoid splitting inside quotes or parens
            # For now, just split and hope for the best
            parts = s.split(op, 1)
            return BinOp(parse_expression(parts[0]), op, parse_expression(parts[1]))
    # Check for function call
    m = re.match(r'(\w+)\((.*)\)', s)
    if m:
        name = m.group(1)
        args_str = m.group(2)
        # Handle multiple args
        args = [parse_expression(a) for a in args_str.split(',') if a.strip()]
        return FuncCall(name, args)
    # Check for literals
    if s.startswith('"') and s.endswith('"'):
        return Literal(s[1:-1])
    try:
        return Literal(float(s) if '.' in s else int(s))
    except ValueError:
        pass
    # Else it's a field
    return Field(s)

class Operator:
    def process(self, record):
        raise NotImplementedError()

class JsonOperator(Operator):
    def __init__(self, from_field=None):
        self.from_field = from_field
    def process(self, record):
        source = record.get(self.from_field) if self.from_field else record.get('_line')
        if not source: return None
        try:
            data = json.loads(source)
            if not isinstance(data, dict): return None
            # Update record with new fields
            new_record = record.copy()
            if not self.from_field:
                del new_record['_line']
            new_record.update(data)
            return new_record
        except:
            return None

class ParseOperator(Operator):
    def __init__(self, pattern, fields, from_field=None):
        self.pattern = pattern
        self.fields = fields
        self.from_field = from_field
        # Convert pattern to regex
        # Escape special chars except *
        regex_pattern = re.escape(pattern).replace(r'\*', '(.*?)')
        self.regex = re.compile('^' + regex_pattern + '$')
    def process(self, record):
        source = record.get(self.from_field) if self.from_field else record.get('_line')
        if not source: return None
        m = self.regex.match(source)
        if m:
            new_record = record.copy()
            if not self.from_field:
                del new_record['_line']
            for i, val in enumerate(m.groups()):
                if i < len(self.fields):
                    # Try to convert to number if possible
                    try:
                        if '.' in val: val = float(val)
                        else: val = int(val)
                    except ValueError:
                        pass
                    new_record[self.fields[i]] = val
            return new_record
        return None

# More operators...

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('query', nargs='?', default='*')
    parser.add_argument('-f', '--file', help='Read from file')
    parser.add_argument('-o', '--output', help='Output format')
    args = parser.parse_args()

    # Simple query parsing
    stages = args.query.split('|')
    filter_part = stages[0].strip()
    # TODO: implement filter logic

    operators = []
    for s in stages[1:]:
        s = s.strip()
        if s.startswith('json'):
            # parse json [from field]
            m = re.match(r'json(?: from (\w+))?', s)
            operators.append(JsonOperator(m.group(1) if m else None))
        elif s.startswith('parse'):
            # parse "pattern" [from field] as f1, f2, ...
            m = re.match(r'parse "(.*?)"(?: from (\w+))? as (.*)', s)
            if m:
                pattern = m.group(1)
                from_field = m.group(2)
                fields = [f.strip() for f in m.group(3).split(',')]
                operators.append(ParseOperator(pattern, fields, from_field))
        # ... other operators ...

    # Input handling
    input_src = open(args.file) if args.file else sys.stdin
    for line in input_src:
        line = line.strip()
        # TODO: apply filter
        record = {'_line': line}
        for op in operators:
            record = op.process(record)
            if record is None: break
        if record:
            # Sort fields by name
            keys = sorted([k for k in record.keys() if k != '_line'])
            if args.output == 'json':
                print(json.dumps({k: record[k] for k in keys}, separators=(',', ':')))
            else:
                # Legacy / Default output
                parts = []
                for k in keys:
                    v = record[k]
                    if isinstance(v, float):
                        v_str = f"{v:.2f}"
                    else:
                        v_str = str(v)
                    parts.append(f"[{k}={v_str}]")
                print("        ".join(parts))

if __name__ == '__main__':
    main()
