            if func.startswith('p') and func[1:].isdigit():
                # This is an aggregator, should not be called here
                return arg_val

        # Check for field access in record
        if s in record:
            return record[s]

        # Handle nested fields (simple dot)
        if '.' in s:
            parts = s.split('.')
            val = record
            for part in parts:
                if isinstance(val, dict) and part in val:
                    val = val[part]
                else:
                    val = None
                    break
            if val is not None: return val

        # Try to parse as literal
        if s.startswith('"') and s.endswith('"'):
            return s[1:-1]
        try:
            if '.' in s: return float(s)
            return int(s)
        except ValueError:
            pass

        # Try simple math (only +-*/ and only between two parts)
        for op in ['+', '-', '*', '/']:
            if op in s:
                parts = s.split(op, 1)
                l = Expression(parts[0]).eval(record)
                r = Expression(parts[1]).eval(record)
                if l is not None and r is not None:
                    try:
                        if op == '+': return l + r
                        if op == '-': return l - r
                        if op == '*': return l * r
                        if op == '/': return l / r
                    except: return None

        return None

class Filter:
    def __init__(self, filter_str):
        self.filter_str = filter_str.strip()
        if self.filter_str == '*':
            self.match = lambda line: True
        elif self.filter_str.startswith('"') and self.filter_str.endswith('"'):
            content = self.filter_str[1:-1]
            self.match = lambda line: content in line
        else:
            # Case-insensitive wildcard match
            regex_str = re.escape(self.filter_str).replace(r'\*', '.*')
            self.regex = re.compile(regex_str, re.I)
            self.match = lambda line: self.regex.search(line)

    def matches(self, line):
        return self.match(line)

class ComplexFilter:
    def __init__(self, query):
        # This is a hacky way to support AND/OR/NOT
        # We replace them with Python and/or/not and eval
        # But we need to handle the individual filters
        self.query = query
        # Tokenize and identify filters
        # Simplified: for now only support simple filters
        self.simple_filter = Filter(query)

    def matches(self, line):
        return self.simple_filter.matches(line)

class Operator:
    def process(self, record): # returns record or None
        raise NotImplementedError()
    def end(self): # returns list of records
        return []

class JsonOperator(Operator):
    def __init__(self, from_field=None):
        self.from_field = from_field
    def process(self, record):
        source = record.get(self.from_field) if self.from_field else record.get('_line')
        if not source: return None
        try:
            data = json.loads(source)
            if not isinstance(data, dict): return None
            new_record = record.copy()
            if not self.from_field: del new_record['_line']
            new_record.update(data)
            return new_record
        except: return None

class LogfmtOperator(Operator):
    def __init__(self, from_field=None):
        self.from_field = from_field
    def process(self, record):
        source = record.get(self.from_field) if self.from_field else record.get('_line')
        if not source: return None
        # Simple logfmt parser
        data = {}
        # This regex handles k=v and k="v"
        matches = re.findall(r'([a-zA-Z0-9_.]+)=("[^"]*"|[^\s]*)', source)
        for k, v in matches:
            if v.startswith('"') and v.endswith('"'): v = v[1:-1]
            else:
                try:
                    if '.' in v: v = float(v)
                    else: v = int(v)
                except ValueError: pass
            data[k] = v
        if not data: return None
        new_record = record.copy()
        if not self.from_field: del new_record['_line']
        new_record.update(data)
        return new_record

class ParseOperator(Operator):
    def __init__(self, pattern, fields, from_field=None):
        self.fields = fields
        self.from_field = from_field
        regex_pattern = re.escape(pattern).replace(r'\*', '(.*?)')
        self.regex = re.compile('^' + regex_pattern + '$')
    def process(self, record):
        source = record.get(self.from_field) if self.from_field else record.get('_line')
        if not source: return None
        m = self.regex.match(source)
        if m:
            new_record = record.copy()
            if not self.from_field: del new_record['_line']
            for i, val in enumerate(m.groups()):
                if i < len(self.fields):
                    try:
                        if '.' in val: val = float(val)
                        else: val = int(val)
                    except ValueError: pass
                    new_record[self.fields[i]] = val
            return new_record
        return None

class WhereOperator(Operator):
    def __init__(self, condition):
        self.condition = condition
    def process(self, record):
        # Very simple: handle "a == b", "a > b", etc.
        m = re.match(r'(.*?) (==|!=|>|<|>=|<=) (.*)', self.condition)
        if m:
            left = Expression(m.group(1)).eval(record)
            op = m.group(2)
            right = Expression(m.group(3)).eval(record)
            if left is None or right is None: return None
            try:
                if op == '==': match = (left == right)
                elif op == '!=': match = (left != right)
                elif op == '>': match = (left > right)
                elif op == '<': match = (left < right)
                elif op == '>=': match = (left >= right)
                elif op == '<=': match = (left <= right)
                else: match = False
                return record if match else None
            except: return None
        return None

class FieldsOperator(Operator):
    def __init__(self, mode, fields):
        self.mode = mode # 'only', 'except', 'add', 'remove'
        self.fields = [f.strip() for f in fields]
    def process(self, record):
        new_record = {}
        if self.mode in ('only', 'add'):
            if self.mode == 'add': new_record = record.copy()
            for f in self.fields:
                if f in record: new_record[f] = record[f]
        elif self.mode in ('except', 'remove'):
            new_record = record.copy()
            for f in self.fields:
                if f in new_record: del new_record[f]
        return new_record

class LimitOperator(Operator):
    def __init__(self, limit):
        self.limit = int(limit)
        self.count = 0
    def process(self, record):
        if self.count < self.limit:
            self.count += 1
            return record
        return None

class ExpressionOperator(Operator):
    def __init__(self, expr, name):
        self.expr = Expression(expr)
        self.name = name
    def process(self, record):
        val = self.expr.eval(record)
        if val is not None:
            new_record = record.copy()
            new_record[self.name] = val
            return new_record
        return record

class TimesliceOperator(Operator):
    def __init__(self, expr, duration, name='_timeslice'):
        self.expr = Expression(expr)
        self.name = name
        # Parse duration: 5m, 1h, etc.
        m = re.match(r'(\d+)([a-z]+)', duration)
        amount = int(m.group(1))
        unit = m.group(2)
        if unit == 's': self.delta = amount
        elif unit == 'm': self.delta = amount * 60
        elif unit == 'h': self.delta = amount * 3600
        elif unit == 'd': self.delta = amount * 86400
        else: self.delta = 60
    def process(self, record):
        dt = self.expr.eval(record)
        if isinstance(dt, datetime):
            ts = dt.timestamp()
            ts = (ts // self.delta) * self.delta
            new_dt = datetime.fromtimestamp(ts, tz=timezone.utc)
            new_record = record.copy()
            new_record[self.name] = new_dt
            return new_record
        return record

class TotalOperator(Operator):
    def __init__(self, expr, name='_total'):
        self.expr = Expression(expr)
        self.name = name
        self.total = 0
    def process(self, record):
        val = self.expr.eval(record)
        if val is not None:
            try: self.total += float(val)
            except: pass
        new_record = record.copy()
        new_record[self.name] = self.total
        return new_record

class SortOperator(Operator):
    def __init__(self, expr, reverse=False):
        self.expr = Expression(expr)
        self.reverse = reverse
        self.records = []
    def process(self, record):
        self.records.append(record)
        return None
    def end(self):
        self.records.sort(key=lambda r: self.expr.eval(r) or 0, reverse=self.reverse)
        return self.records

class AggregatorStage(Operator):
    def __init__(self, aggregators, by_fields=None):
        self.aggregators = aggregators # list of (type, expr, name)
        self.by_fields = by_fields or []
        self.groups = collections.defaultdict(lambda: [None] * len(aggregators))
        # state for each aggregator in each group
        self.state = collections.defaultdict(lambda: [None] * len(aggregators))

    def process(self, record):
        key = tuple(Expression(f).eval(record) for f in self.by_fields)
        for i, (agg_type, expr, name) in enumerate(self.aggregators):
            val = Expression(expr).eval(record) if expr else None
            curr = self.state[key][i]
            if agg_type == 'count':
                self.state[key][i] = (curr or 0) + 1
            elif agg_type == 'sum':
                if val is not None: self.state[key][i] = (curr or 0) + float(val)
            elif agg_type == 'min':
                if val is not None: self.state[key][i] = min(curr, float(val)) if curr is not None else float(val)
            elif agg_type == 'max':
                if val is not None: self.state[key][i] = max(curr, float(val)) if curr is not None else float(val)
            elif agg_type == 'average':
                if val is not None:
                    if curr is None: self.state[key][i] = (float(val), 1)
                    else: self.state[key][i] = (curr[0] + float(val), curr[1] + 1)
            elif agg_type.startswith('p') and agg_type[1:].isdigit():
                if val is not None:
                    if curr is None: self.state[key][i] = [float(val)]
                    else: curr.append(float(val))
            elif agg_type == 'count_distinct':
                if val is not None:
                    if curr is None: self.state[key][i] = {val}
                    else: curr.add(val)
        return None

    def end(self):
        results = []
        for key, states in self.state.items():
            record = {}
            for i, f in enumerate(self.by_fields):
                record[f] = key[i]
            for i, (agg_type, expr, name) in enumerate(self.aggregators):
                curr = states[i]
                res = None
                if agg_type == 'count': res = curr or 0
                elif agg_type == 'sum': res = curr or 0
                elif agg_type == 'min': res = curr
                elif agg_type == 'max': res = curr
                elif agg_type == 'average': res = (curr[0] / curr[1]) if curr else 0
                elif agg_type.startswith('p') and agg_type[1:].isdigit():
                    if curr:
                        curr.sort()
                        p = int(agg_type[1:])
                        idx = int(len(curr) * p / 100)
                        res = curr[min(idx, len(curr)-1)]
                elif agg_type == 'count_distinct': res = len(curr) if curr else 0
                record[name] = res
            results.append(record)
        return results

def split_query(query):
    stages = []
    current = ""
    in_quote = False
    in_paren = 0
    for char in query:
        if char == '"': in_quote = not in_quote; current += char
        elif char == '(' and not in_quote: in_paren += 1; current += char
        elif char == ')' and not in_quote: in_paren -= 1; current += char
        elif char == '|' and not in_quote and in_paren == 0:
            stages.append(current.strip()); current = ""
        else: current += char
    stages.append(current.strip())
    return [s for s in stages if s]

def parse_operators(stages):
    ops = []
    for s in stages:
        if s.startswith('json'):
            m = re.match(r'json(?: from ([\w.]+))?', s)
            ops.append(JsonOperator(m.group(1) if m else None))
        elif s.startswith('logfmt'):
            m = re.match(r'logfmt(?: from ([\w.]+))?', s)
            ops.append(LogfmtOperator(m.group(1) if m else None))
        elif s.startswith('parse'):
            m = re.match(r'parse "(.*?)"(?: from (\w+))? as (.*)', s)
            if m:
                pattern = m.group(1)
                from_field = m.group(2)
                fields = [f.strip().strip('[]"') for f in m.group(3).split(',')]
                ops.append(ParseOperator(pattern, fields, from_field))
        elif s.startswith('where'):
            ops.append(WhereOperator(s[5:].strip()))
        elif s.startswith('fields'):
            parts = s[6:].strip().split(' ', 1)
            mode = 'only'
            f_str = s[6:].strip()
            if parts[0] in ('only', 'except', '+', '-'):
                mode = {'+': 'add', '-': 'remove'}.get(parts[0], parts[0])
                f_str = parts[1]
            ops.append(FieldsOperator(mode, [f.strip() for f in f_str.split(',')]))
        elif s.startswith('limit'):
            ops.append(LimitOperator(s[5:].strip()))
        elif s.startswith('sort'):
            m = re.match(r'sort by (.*?)(?: (asc|desc))?$', s)
            if m: ops.append(SortOperator(m.group(1).strip(), m.group(2) == 'desc'))
        elif s.startswith('timeslice'):
            m = re.match(r'timeslice\((.*?)\) (\d+[a-z]+)(?: as (\w+))?', s)
            if m: ops.append(TimesliceOperator(m.group(1), m.group(2), m.group(3) or '_timeslice'))
        elif s.startswith('total'):
            m = re.match(r'total\((.*?)\)(?: as (\w+))?', s)
            if m: ops.append(TotalOperator(m.group(1), m.group(2) or '_total'))
        else:
            # Check for aggregators or "expr as name"
            if ' as ' in s and '(' not in s.split(' as ')[0]:
                parts = s.split(' as ')
                ops.append(ExpressionOperator(parts[0].strip(), parts[1].strip()))
            else:
                # Potential aggregate stage
                aggs = []
                by_fields = []
                if ' by ' in s:
                    s_aggs, s_by = s.rsplit(' by ', 1)
                    by_fields = [f.strip().strip('[]"') for f in s_by.split(',')]
                else:
                    s_aggs = s

                for agg_s in s_aggs.split(','):
                    agg_s = agg_s.strip()
                    m = re.match(r'(\w+)\((.*?)\)(?: as (\w+))?', agg_s)
                    if m:
                        agg_type = m.group(1)
                        expr = m.group(2)
                        name = m.group(3) or (f"_{agg_type}" if agg_type != 'p50' else 'p50') # hack for p50
                        if agg_type.startswith('p') and agg_type[1:].isdigit() and not m.group(3):
                            name = agg_type
                        aggs.append((agg_type, expr, name))
                    elif agg_s.startswith('count'):
                        m = re.match(r'count(?: as (\w+))?', agg_s)
                        aggs.append(('count', None, (m.group(1) if m else '_count')))
                if aggs:
                    ops.append(AggregatorStage(aggs, by_fields))
    return ops

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('query', nargs='?', default='*')
    parser.add_argument('-f', '--file', help='Read from file')
    parser.add_argument('-o', '--output', help='Output format')
    parser.add_argument('-v', '--version', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')
    args, unknown = parser.parse_known_args()

    if args.version:
        print("ag 0.19.6")
        return
    if args.help:
        print("Usage: executable [OPTIONS] [QUERY]")
        return

    stages = split_query(args.query)
    filter_query = stages[0]
    operators = parse_operators(stages[1:])

    is_aggregate = any(isinstance(op, (AggregatorStage, SortOperator)) for op in operators)

    def process_pipeline(record, ops_list):
        for i, op in enumerate(ops_list):
            record = op.process(record)
            if record is None:
                # If it's a blocking operator, we don't return None,
                # we return None because the record was consumed.
                return None
        return record

    input_src = open(args.file) if args.file else sys.stdin
    try:
        f = ComplexFilter(filter_query)
        for line in input_src:
            line = line.strip()
            if not f.matches(line): continue
            record = {'_line': line}
            res = process_pipeline(record, operators)
            if res and not is_aggregate:
                output_record(res, args.output)
    except KeyboardInterrupt:
        pass
    finally:
        if is_aggregate:
            # Handle blocking operators
            records = [None] # Dummy
            current_ops = operators
            while True:
                # Find first blocking op
                found_blocking = False
                for i, op in enumerate(current_ops):
                    if isinstance(op, (AggregatorStage, SortOperator)):
                        new_records = op.end()
                        remaining_ops = current_ops[i+1:]
                        found_blocking = True

                        final_records = []
                        for r in new_records:
                            res = process_pipeline(r, remaining_ops)
                            if res: final_records.append(res)
                        records = final_records
                        break
                if not found_blocking: break
                current_ops = [] # Already processed remaining

            if records:
                output_table(records, args.output)

def output_record(record, format_type):
    keys = sorted([k for k in record.keys() if k != '_line'])
    if format_type == 'json':
        print(json.dumps({k: record[k] for k in keys}, separators=(',', ':')))
    elif format_type == 'logfmt':
        print(" ".join(f"{k}={format_value(record[k])}" for k in keys))
    elif format_type and format_type.startswith('format='):
        fmt = format_type[7:]
        print(fmt.format(**record))
    else:
        # Legacy
        parts = []
        for k in keys:
            parts.append(f"[{k}={format_value(record[k])}]")
        print("        ".join(parts))

def output_table(records, format_type):
    if not records: return
    keys = []
    # Identify all keys
    for r in records:
        for k in r.keys():
            if k not in keys: keys.append(k)

    if format_type == 'json':
        for r in records: output_record(r, format_type)
        return

    # Calculate widths
    widths = {k: len(k) for k in keys}
    for r in records:
        for k in keys:
            widths[k] = max(widths[k], len(format_value(r.get(k))))

    # Print header
    header = "        ".join(k.ljust(widths[k]) for k in keys)
    print(header)
    print("-" * (sum(widths.values()) + 8 * (len(keys)-1)))
    for r in records:
        print("        ".join(format_value(r.get(k)).ljust(widths[k]) for k in keys))

if __name__ == '__main__':
    main()
