        m = re.match(r'(\d+)([a-z]+)', duration)
        amount = int(m.group(1))
        unit = m.group(2)
        if unit == 's': self.delta = amount
        elif unit == 'm': self.delta = amount * 60
        elif unit == 'h': self.delta = amount * 3600
        elif unit == 'd': self.delta = amount * 86400
        else: self.delta = 60
    def process(self, record):
        dt = self.expr.eval(record)
        if isinstance(dt, datetime):
            ts = dt.timestamp()
            ts = (ts // self.delta) * self.delta
            new_dt = datetime.fromtimestamp(ts, tz=timezone.utc)
            new_record = record.copy()
            new_record[self.name] = new_dt
