class AggregatorStage(Operator):
    def __init__(self, aggregators, by_fields=None):
        self.aggregators = aggregators # list of (type, expr, name)
        self.by_fields = by_fields or []
        self.groups = collections.defaultdict(lambda: [None] * len(aggregators))
        # state for each aggregator in each group
        self.state = collections.defaultdict(lambda: [None] * len(aggregators))

    def process(self, record):
        key = tuple(Expression(f).eval(record) for f in self.by_fields)
        for i, (agg_type, expr, name) in enumerate(self.aggregators):
            val = Expression(expr).eval(record) if expr else None
            curr = self.state[key][i]
            if agg_type == 'count':
                self.state[key][i] = (curr or 0) + 1
            elif agg_type == 'sum':
                if val is not None: self.state[key][i] = (curr or 0) + float(val)
            elif agg_type == 'min':
                if val is not None: self.state[key][i] = min(curr, float(val)) if curr is not None else float(val)
            elif agg_type == 'max':
                if val is not None: self.state[key][i] = max(curr, float(val)) if curr is not None else float(val)
            elif agg_type == 'average':
                if val is not None:
                    if curr is None: self.state[key][i] = (float(val), 1)
                    else: self.state[key][i] = (curr[0] + float(val), curr[1] + 1)
