    in_paren = 0
    for char in query:
        if char == '"': in_quote = not in_quote; current += char
        elif char == '(' and not in_quote: in_paren += 1; current += char
        elif char == ')' and not in_quote: in_paren -= 1; current += char
        elif char == '|' and not in_quote and in_paren == 0:
            stages.append(current.strip()); current = ""
        else: current += char
    stages.append(current.strip())
    return [s for s in stages if s]

def parse_operators(stages):
    ops = []
    for s in stages:
        if s.startswith('json'):
            m = re.match(r'json(?: from ([\w.]+))?', s)
            ops.append(JsonOperator(m.group(1) if m else None))
        elif s.startswith('logfmt'):
            m = re.match(r'logfmt(?: from ([\w.]+))?', s)
            ops.append(LogfmtOperator(m.group(1) if m else None))
        elif s.startswith('parse'):
            m = re.match(r'parse "(.*?)"(?: from (\w+))? as (.*)', s)
            if m:
                pattern = m.group(1)
                from_field = m.group(2)
                fields = [f.strip().strip('[]"') for f in m.group(3).split(',')]
                ops.append(ParseOperator(pattern, fields, from_field))
        elif s.startswith('where'):
            ops.append(WhereOperator(s[5:].strip()))
        elif s.startswith('fields'):
            parts = s[6:].strip().split(' ', 1)
            mode = 'only'
            f_str = s[6:].strip()
            if parts[0] in ('only', 'except', '+', '-'):
                mode = {'+': 'add', '-': 'remove'}.get(parts[0], parts[0])
                f_str = parts[1]
            ops.append(FieldsOperator(mode, [f.strip() for f in f_str.split(',')]))
        elif s.startswith('limit'):
            ops.append(LimitOperator(s[5:].strip()))
        elif s.startswith('sort'):
            m = re.match(r'sort by (.*?)(?: (asc|desc))?$', s)
            if m: ops.append(SortOperator(m.group(1).strip(), m.group(2) == 'desc'))
        elif s.startswith('timeslice'):
            m = re.match(r'timeslice\((.*?)\) (\d+[a-z]+)(?: as (\w+))?', s)
            if m: ops.append(TimesliceOperator(m.group(1), m.group(2), m.group(3) or '_timeslice'))
        elif s.startswith('total'):
            m = re.match(r'total\((.*?)\)(?: as (\w+))?', s)
            if m: ops.append(TotalOperator(m.group(1), m.group(2) or '_total'))
        else:
            # Check for aggregators or "expr as name"
            if ' as ' in s and '(' not in s.split(' as ')[0]:
                parts = s.split(' as ')
                ops.append(ExpressionOperator(parts[0].strip(), parts[1].strip()))
            else:
                # Potential aggregate stage
                aggs = []
                by_fields = []
                if ' by ' in s:
                    s_aggs, s_by = s.rsplit(' by ', 1)
                    by_fields = [f.strip().strip('[]"') for f in s_by.split(',')]
                else:
                    s_aggs = s

                for agg_s in s_aggs.split(','):
                    agg_s = agg_s.strip()
                    m = re.match(r'(\w+)\((.*?)\)(?: as (\w+))?', agg_s)
                    if m:
                        agg_type = m.group(1)
                        expr = m.group(2)
                        name = m.group(3) or (f"_{agg_type}" if agg_type != 'p50' else 'p50') # hack for p50
                        if agg_type.startswith('p') and agg_type[1:].isdigit() and not m.group(3):
                            name = agg_type
                        aggs.append((agg_type, expr, name))
                    elif agg_s.startswith('count'):
                        m = re.match(r'count(?: as (\w+))?', agg_s)
                        aggs.append(('count', None, (m.group(1) if m else '_count')))
                if aggs:
                    ops.append(AggregatorStage(aggs, by_fields))
    return ops

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('query', nargs='?', default='*')
    parser.add_argument('-f', '--file', help='Read from file')
    parser.add_argument('-o', '--output', help='Output format')
