        return

    stages = split_query(args.query)
    filter_query = stages[0]
    operators = parse_operators(stages[1:])

    is_aggregate = any(isinstance(op, (AggregatorStage, SortOperator)) for op in operators)

    def process_pipeline(record, ops_list):
        for i, op in enumerate(ops_list):
            record = op.process(record)
            if record is None:
                # If it's a blocking operator, we don't return None,
                # we return None because the record was consumed.
