            record = {'_line': line}
            res = process_pipeline(record, operators)
            if res and not is_aggregate:
                output_record(res, args.output)
    except KeyboardInterrupt:
        pass
    finally:
        if is_aggregate:
            # Handle blocking operators
            records = [None] # Dummy
            current_ops = operators
            while True:
                # Find first blocking op
                found_blocking = False
                for i, op in enumerate(current_ops):
                    if isinstance(op, (AggregatorStage, SortOperator)):
                        new_records = op.end()
                        remaining_ops = current_ops[i+1:]
                        found_blocking = True

                        final_records = []
                        for r in new_records:
                            res = process_pipeline(r, remaining_ops)
                            if res: final_records.append(res)
                        records = final_records
                        break
                if not found_blocking: break
                current_ops = [] # Already processed remaining

            if records:
                output_table(records, args.output)

def output_record(record, format_type):
    keys = sorted([k for k in record.keys() if k != '_line'])
    if format_type == 'json':
        print(json.dumps({k: record[k] for k in keys}, separators=(',', ':')))
    elif format_type == 'logfmt':
        print(" ".join(f"{k}={format_value(record[k])}" for k in keys))
    elif format_type and format_type.startswith('format='):
        fmt = format_type[7:]
        print(fmt.format(**record))
    else:
        # Legacy
        parts = []
        for k in keys:
            parts.append(f"[{k}={format_value(record[k])}]")
        print("        ".join(parts))

def output_table(records, format_type):
    if not records: return
    keys = []
    # Identify all keys
    for r in records:
        for k in r.keys():
            if k not in keys: keys.append(k)

    if format_type == 'json':
        for r in records: output_record(r, format_type)
        return

    # Calculate widths
    widths = {k: len(k) for k in keys}
    for r in records:
        for k in keys:
            widths[k] = max(widths[k], len(format_value(r.get(k))))

    # Print header
    header = "        ".join(k.ljust(widths[k]) for k in keys)
    print(header)
    print("-" * (sum(widths.values()) + 8 * (len(keys)-1)))
    for r in records:
        print("        ".join(format_value(r.get(k)).ljust(widths[k]) for k in keys))

if __name__ == '__main__':
    main()
