        self.expr, self.name = Expression(expr), name
        m = re.match(r'(\d+)([a-z]+)', dur)
        num, unit = int(m.group(1)), m.group(2)
        self.delta = num * {'s':1, 'm':60, 'h':3600, 'd':86400}.get(unit, 60)
    def process(self, record):
        dt = self.expr.eval(record)
        if isinstance(dt, datetime):
            ts = (dt.timestamp() // self.delta) * self.delta
            res = record.copy()
            res[self.name] = datetime.fromtimestamp(ts, tz=timezone.utc)
            return res
        return record

class TotalOperator(Operator):
    def __init__(self, expr, name='_total'): self.expr, self.name, self.total = Expression(expr), name, 0
    def process(self, record):
        try: self.total += float(self.expr.eval(record) or 0)
        except: pass
        res = record.copy()
        res[self.name] = self.total
        return res

class SortOperator(Operator):
    def __init__(self, expr, rev=False): self.expr, self.rev, self.recs = Expression(expr), rev, []
    def process(self, record): self.recs.append(record); return None
    def end(self): self.recs.sort(key=lambda r: self.expr.eval(r) or 0, reverse=self.rev); return self.recs

class AggregatorStage(Operator):
    def __init__(self, aggs, by_fields): self.aggs, self.by_fields, self.state = aggs, by_fields, collections.defaultdict(lambda: [None]*len(aggs))
    def process(self, record):
        key = tuple(Expression(f).eval(record) for f in self.by_fields)
        for i, (typ, expr, name) in enumerate(self.aggs):
            val = Expression(expr).eval(record) if expr else None
            curr = self.state[key][i]
            if typ == 'count': self.state[key][i] = (curr or 0) + 1
            elif typ == 'sum': self.state[key][i] = (curr or 0) + float(val or 0)
            elif typ == 'min': self.state[key][i] = min(curr, float(val)) if curr is not None else float(val)
            elif typ == 'max': self.state[key][i] = max(curr, float(val)) if curr is not None else float(val)
            elif typ == 'average':
                if curr is None: self.state[key][i] = (float(val or 0), 1)
                else: self.state[key][i] = (curr[0] + float(val or 0), curr[1] + 1)
            elif typ.startswith('p') and typ[1:].isdigit():
                if curr is None: self.state[key][i] = [float(val or 0)]
                else: curr.append(float(val or 0))
            elif typ == 'count_distinct':
                if curr is None: self.state[key][i] = {val}
                else: curr.add(val)
        return None
