            ops.append(LogfmtOperator(m.group(1)))
        elif s.startswith('parse'):
            m = re.match(r'parse "(.*?)"(?: from (\w+))? as (.*)', s)
            if m: ops.append(ParseOperator(m.group(1), [f.strip().strip('[]"') for f in m.group(3).split(',')], m.group(2)))
        elif s.startswith('where'): ops.append(WhereOperator(s[5:].strip()))
        elif s.startswith('fields'):
            m = re.match(r'fields (only|except|\+|\-) (.*)', s)
            if m: ops.append(FieldsOperator({'only':'only','except':'except','+':'add','-':'remove'}[m.group(1)], [f.strip() for f in m.group(2).split(',')]))
            else: ops.append(FieldsOperator('only', [f.strip() for f in s[6:].strip().split(',')]))
