        if isinstance(d, datetime):
            ts = (d.timestamp() // self.dt) * self.dt
            res = r.copy(); res[self.name if hasattr(self,'name') else self.n] = datetime.fromtimestamp(ts, tz=timezone.utc); return res
        return r

class TotalOp(Operator):
    def __init__(self, e, n='_total'): self.e, self.n, self.t = Expression(e), n, 0
    def process(self, r):
        try: self.t += float(self.e.eval(r) or 0)
        except: pass
        res = r.copy(); res[self.n] = self.t; return res

class SortOp(Operator):
    def __init__(self, e, rv=False): self.e, self.rv, self.rs = Expression(e), rv, []
    def process(self, r): self.rs.append(r); return None
    def end(self): self.rs.sort(key=lambda r: self.e.eval(r) or 0, reverse=self.rv); return self.rs

class AggStage(Operator):
    def __init__(self, aggs, bfs): self.aggs, self.bfs, self.st = aggs, bfs, collections.defaultdict(lambda: [None]*len(aggs))
    def process(self, r):
        k = tuple(Expression(f).eval(r) for f in self.bfs)
        for i, (t, e, n) in enumerate(self.aggs):
            v = Expression(e).eval(r) if e else None
            c = self.st[k][i]
            if t == 'count': self.st[k][i] = (c or 0) + 1
            elif t == 'sum': self.st[k][i] = (c or 0) + float(v or 0)
            elif t == 'min': self.st[k][i] = min(c, float(v)) if c is not None else float(v)
            elif t == 'max': self.st[k][i] = max(c, float(v)) if c is not None else float(v)
            elif t == 'average':
                if c is None: self.st[k][i] = (float(v or 0), 1)
                else: self.st[k][i] = (c[0] + float(v or 0), c[1] + 1)
            elif t.startswith('p') and t[1:].isdigit():
                if c is None: self.st[k][i] = [float(v or 0)]
                else: c.append(float(v or 0))
            elif t == 'count_distinct':
                if c is None: self.st[k][i] = {v}
                else: c.add(v)
        return None
    def end(self):
        res = []
        for k, sts in self.st.items():
            r = {f: k[i] for i, f in enumerate(self.bfs)}
            for i, (t, e, n) in enumerate(self.aggs):
                s = sts[i]
                if t == 'count' or t == 'sum': val = s or 0
                elif t in ('min', 'max'): val = s
                elif t == 'average': val = s[0]/s[1] if s else 0
                elif t.startswith('p'):
                    if not s: val = 0
                    else:
                        s.sort(); p = int(t[1:])
                        val = s[min(int(len(s)*p/100), len(s)-1)]
                elif t == 'count_distinct': val = len(s) if s else 0
                r[n] = val
            res.append(r)
        return res

def parse_o(stages):
    ops = []
    for s in stages:
        if s.startswith('json'):
            m = re.match(r'json(?: from ([\w.]+))?', s)
            ops.append(JsonOp(m.group(1)))
        elif s.startswith('logfmt'):
            m = re.match(r'logfmt(?: from ([\w.]+))?', s)
            ops.append(LogfmtOp(m.group(1)))
        elif s.startswith('parse'):
            nc = 'noconvert' in s
            s = s.replace('noconvert', '').strip()
            m = re.match(r'parse "(.*?)"(?: from (\w+))? as (.*)', s)
            if m: ops.append(ParseOp(m.group(1), [f.strip().strip('[]"') for f in m.group(3).split(',')], m.group(2), nc))
        elif s.startswith('where'): ops.append(WhereOp(s[5:].strip()))
        elif s.startswith('fields'):
            m = re.match(r'fields (only|except|\+|\-) (.*)', s)
            if m: ops.append(FieldsOp({'only':'only','except':'except','+':'add','-':'remove'}[m.group(1)], [f.strip() for f in m.group(2).split(',')]))
            else: ops.append(FieldsOp('only', [f.strip() for f in s[6:].strip().split(',')]))
        elif s.startswith('limit'): ops.append(LimitOp(s[5:].strip()))
        elif s.startswith('sort'):
            m = re.match(r'sort by (.*?)(?: (asc|desc))?$', s)
            if m: ops.append(SortOp(m.group(1).strip(), m.group(2) == 'desc'))
        elif s.startswith('timeslice'):
            m = re.match(r'timeslice\((.*?)\) (\d+[a-z]+)(?: as (\w+))?', s)
            if m: ops.append(TimesliceOp(m.group(1), m.group(2), m.group(3) or '_timeslice'))
        elif s.startswith('total'):
            m = re.match(r'total\((.*?)\)(?: as (\w+))?', s)
            if m: ops.append(TotalOp(m.group(1), m.group(2) or '_total'))
        elif ' as ' in s and '(' not in s.split(' as ')[0]:
            p = s.split(' as '); ops.append(ExprOp(p[0].strip(), p[1].strip()))
        else:
            by = []; sa = s
            if ' by ' in s: sa, sb = s.rsplit(' by ', 1); by = [f.strip().strip('[]"') for f in sb.split(',')]
            aggs = []
            for a in sa.split(','):
                a = a.strip(); m = re.match(r'(\w+)\((.*?)\)(?: as (\w+))?', a)
                if m:
                    t, e, n = m.group(1), m.group(2), m.group(3)
                    if not n: n = t if (t.startswith('p') and t[1:].isdigit()) else f"_{t}"
                    aggs.append((t, e, n))
                elif a.startswith('count'):
                    m = re.match(r'count(?: as (\w+))?', a)
                    aggs.append(('count', None, m.group(1) or '_count'))
            if aggs: ops.append(AggStage(aggs, by))
    return ops

def main():
    p = argparse.ArgumentParser(add_help=False); p.add_argument('query', nargs='?', default='*')
    p.add_argument('-f', '--file'); p.add_argument('-o', '--output'); p.add_argument('-v', '--version', action='store_true'); p.add_argument('-h', '--help', action='store_true')
    args, _ = p.parse_known_args()
    if args.version: print("ag 0.19.6"); return
    if args.help: print("Usage: executable [OPTIONS] [QUERY]"); return
    st = split_q(args.query); flt = ComplexFilter(st[0]); ops = parse_o(st[1:])
    src = open(args.file) if args.file else sys.stdin
    try:
        for l in src:
            l = l.strip()
            if not flt.matches(l): continue
            r = {'_line': l}
            for op in ops:
                r = op.process(r)
                if r is None: break
            if r:
                ks = sorted([k for k in r.keys() if k != '_line'])
                if args.output == 'json': print(json.dumps({k: r[k] for k in ks}, separators=(',', ':')))
                elif args.output == 'logfmt': print(" ".join(f"{k}={format_val(r[k])}" for k in ks))
                elif args.output and args.output.startswith('format='): print(args.output[7:].format(**r))
                else: print("        ".join(f"[{k}={format_val(r[k])}]" for k in ks))
    except KeyboardInterrupt: pass
    finally:
        recs = []
        for i, op in enumerate(ops):
            if isinstance(op, (AggStage, SortOp)):
                recs = op.end()
                for n_op in ops[i+1:]:
                    n_recs = []
                    for r in recs:
                        res = n_op.process(r)
                        if res: n_recs.append(res)
                    recs = n_recs + n_op.end()
                break
        if recs:
            ks = []
            for r in recs:
                for k in r.keys():
                    if k not in ks: ks.append(k)
            if args.output == 'json':
                for r in recs: print(json.dumps({k: r.get(k) for k in sorted(ks)}, separators=(',', ':')))
                return
            ws = {k: max(len(k), max([len(format_val(r.get(k))) for r in recs])) for k in ks}
            print("        ".join(k.ljust(ws[k]) for k in ks))
            print("-" * (sum(ws.values()) + 8 * (len(ks)-1)))
            for r in recs: print("        ".join(format_val(r.get(k)).ljust(ws[k]) for k in ks))

def split_q(q):
    res, cur, qte, par = [], "", False, 0
    for c in q:
        if c == '"': qte = not qte; cur += c
        elif c == '(' and not qte: par += 1; cur += c
        elif c == ')' and not qte: par -= 1; cur += c
        elif c == '|' and not qte and par == 0: res.append(cur.strip()); cur = ""
        else: cur += c
    res.append(cur.strip()); return [s for s in res if s]

if __name__ == '__main__': main()
